Cho biết kết quả hiển thị của đoạn mã sau:
```cpp
#include <iostream>
using namespace std;

int* f(int list1[], const int list2[], int size)
{
  for (int i = 0; i < size; i++)
    list1[i] += list2[i];
  return list1;
}

int main()
{
  int list1[] = {1, 2, 3, 4};
  int list2[] = {1, 2, 3, 4};
  int* p = f(list1, list2, 4);
  cout << p[0] << endl;
  cout << p[1] << endl;

  return 0;
}
```

