example.code:
#include <iostream>
#include <algorithm>

int main()
{
    int list[] = {4, 2, 3, 6, 5, 1};
    const int size = 6;

    int* minPtr = std::min_element(list, list + size);
    int* maxPtr = std::max_element(list, list + size);

    std::cout << "Min: " << *minPtr << " at index " << (minPtr - list) << "\n";
    std::cout << "Max: " << *maxPtr << " at index " << (maxPtr - list) << "\n";

    std::sort(list, list + size);
    std::cout << "Sorted: ";
    for (int i = 0; i < size; ++i)
    {
        std::cout << list[i] << " ";
    }
    std::cout << "\n";

    int key = 4;
    int* findPtr = std::find(list, list + size, key);
    if (findPtr != list + size)
    {
        std::cout << "Found " << *findPtr << " at index " << (findPtr - list) << "\n";
    }
    else
    {
        std::cout << "Value not found\n";
    }

    return 0;
}

#include <iostream>

// Allocates a persistent reversed array on the heap
int* reverseArray(const int* list, int size)
{
    int* result = new int[size];
    for (int i = 0, j = size - 1; i < size; ++i, --j)
    {
        result[j] = list[i];
    }
    return result;
}

void printArray(const int* list, int size)
{
    for (int i = 0; i < size; ++i)
    {
        std::cout << list[i] << (i == size - 1 ? "" : " ");
    }
    std::cout << "\n";
}

int main()
{
    int original[] = {1, 2, 3, 4, 5, 6};
    const int size = 6;

    int* reversed = reverseArray(original, size);

    std::cout << "Original: ";
    printArray(original, size);

    std::cout << "Reversed: ";
    printArray(reversed, size);

    // Clean up heap allocated memory
    delete[] reversed;

    return 0;
}
